contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entrypoint that exercises deposit, withdraw, and refund behaviours
    function run(address toWithdrawFrom, uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");
        // initial observable values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeCallerBalanceInC = c.balances(address(this));

        // perform a deposit into c from this test contract
        c.deposit{value: depositAmt}();

        // after deposit values
        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositCallerBalanceInC = c.balances(address(this));

        // The deposit should increase both the contract's ether and the reported caller balance by the same amount
        assert(afterDepositContractBalance == beforeContractBalance + depositAmt);
        assert(afterDepositCallerBalanceInC == beforeCallerBalanceInC + depositAmt);

        // Try a withdraw: capture whether it reverts
        bool withdrewReverted;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Read post-withdraw observable values
        uint256 afterWithdrawContractBalance = address(c).balance;
        uint256 afterWithdrawCallerBalanceInC = c.balances(address(this));

        // If withdraw did not revert then withdrawAmt must have been <= caller's balance before withdraw,
        // and the sum (contract balance + caller's recorded balance) must be equal to the sum just after deposit
        // (Ether conserved between contract and account-recorded balance).
        assert(
            withdrewReverted
            || (withdrawAmt <= afterDepositCallerBalanceInC && (afterWithdrawContractBalance + afterWithdrawCallerBalanceInC) == (afterDepositContractBalance + afterDepositCallerBalanceInC))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot access C.balances (it's not public), so we observe effects via address(c).balance
    // and transfers received by this contract (address(this).balance). The test performs a deposit
    // then attempts a withdraw and asserts the high-level invariants described above.
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // record observable before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // perform deposit into C from this contract
        c.deposit{value: depositAmt}();

        // after deposit observable values
        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositThisBalance = address(this).balance;

        // The deposit must have increased the contract's balance by depositAmt and decreased this contract's balance by depositAmt
        // (these are observable). If depositAmt == 0 the balances remain equal; in general:
        // afterContract = beforeContract + depositAmt
        // afterThis = beforeThis - depositAmt
        assert(afterDepositContractBalance == beforeContractBalance + depositAmt);
        assert(afterDepositThisBalance + depositAmt == beforeThisBalance);

        // Try withdraw and capture whether it reverts. If it succeeds, this contract will receive Ether.
        bool withdrewReverted;
        uint256 beforeWithdrawThisBalance = address(this).balance;
        uint256 beforeWithdrawContractBalance = address(c).balance;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint256 afterWithdrawThisBalance = address(this).balance;
        uint256 afterWithdrawContractBalance = address(c).balance;

        // General rule (single assert):
        // Either the withdraw reverted, or if it succeeded then:
        // 1) The caller (this contract) received at most withdrawAmt (it may receive exactly withdrawAmt).
        // 2) The contract's observable balance decreased by the same amount this contract's balance increased.
        // 3) The withdraw could only succeed when withdrawAmt was <= the caller's recorded balance; we cannot read that balance
        //    directly, but property (2) together with deposit behavior ensures conservation of observable ether between C and this.
        // We express this as: if not reverted then (afterContract + afterThis) == (beforeWithdrawContractBalance + beforeWithdrawThisBalance)
        // and afterThis >= beforeWithdrawThisBalance && (afterWithdrawContractBalance <= beforeWithdrawContractBalance).

        assert(
            withdrewReverted
            || (
                // conservation of observable ether between C and this contract on successful withdraw
                (afterWithdrawContractBalance + afterWithdrawThisBalance) == (beforeWithdrawContractBalance + beforeWithdrawThisBalance)
                // this contract's balance did not decrease when withdraw succeeded
                && afterWithdrawThisBalance >= beforeWithdrawThisBalance
                // contract's balance did not increase when withdraw succeeded
                && afterWithdrawContractBalance <= beforeWithdrawContractBalance
            )
        );
    }

    // allow receiving Ether from C.withdraw / refund
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with all logic
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // record observable before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // perform deposit into C from this contract
        c.deposit{value: depositAmt}();

        // record values right before withdraw attempt
        uint256 beforeWithdrawContractBalance = address(c).balance;
        uint256 beforeWithdrawThisBalance = address(this).balance;

        // attempt withdraw and capture revert status
        bool withdrewReverted;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // record after-values
        uint256 afterWithdrawContractBalance = address(c).balance;
        uint256 afterWithdrawThisBalance = address(this).balance;

        // Single assert: if withdraw succeeded then observable ether is conserved and this contract's balance did not decrease
        assert(
            withdrewReverted
            || (
                (afterWithdrawContractBalance + afterWithdrawThisBalance) == (beforeWithdrawContractBalance + beforeWithdrawThisBalance)
                && afterWithdrawThisBalance >= beforeWithdrawThisBalance
            )
        );
    }

    // receive to accept refunds/withdraw transfers
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable creator;

    constructor(C _c) { c = _c; creator = payable(address(this)); }

    // single public function with all logic
    // params: a flag indicating whether to call migrateTo (by creator) and a target address to migrate to
    function run(bool callMigrate, address payable target) public payable {
        // No precondition needed about msg.value; we will avoid calling deposit to not trigger C.deposit's assert.
        // Record observable contract balance before any action
        uint256 beforeContractBalance = address(c).balance;

        // Attempt to call migrateTo from this contract when requested; capture whether it reverted
        bool migrateReverted;
        if (callMigrate) {
            try c.migrateTo(target) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        } else {
            migrateReverted = true; // if we didn't call it, treat as reverted for the property shape
        }

        // After the (possible) migrate call, record observable contract balance
        uint256 afterContractBalance = address(c).balance;

        // Now: try withdrawing the entire recorded balance (as visible to C via withdraw require) from this contract
        // Since balances mapping is private, we infer whether withdraw will revert by attempting with a large amount and catching
        bool withdrawReverted;
        try c.withdraw(type(uint256).max) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Assert a general rule: migrateTo, when it does not revert, cannot transfer out more than the observable balance (so afterContractBalance <= beforeContractBalance)
        // and migrateTo must not cause withdraw to suddenly succeed if there was no observable contract balance remaining to fund a withdraw (i.e., if afterContractBalance == 0 then withdraw must revert).
        // We express this as a single boolean formula.
        assert(
            (
                // if migrate call was not made, don't constrain the balances beyond the relation between before/after
                (!callMigrate) || (
                    migrateReverted || afterContractBalance <= beforeContractBalance
                )
            )
            && (
                // if there's no observable balance left after migrate, then withdrawing (an attempt to withdraw a large amount) must revert
                (afterContractBalance != 0) || withdrawReverted
            )
        );
    }

    // receive to accept any ether sent during migrateTo
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function with all logic
    // params: whether to call migrateTo, and the target to migrate to
    function run(bool doMigrate, address payable target) public payable {
        require(true);

        // record balance before any action
        uint256 beforeBalance = address(c).balance;

        // perform migrateTo if requested, catching revert
        bool migrateReverted;
        if (doMigrate) {
            try c.migrateTo(target) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        } else {
            migrateReverted = true;
        }

        // record balance after migrate attempt
        uint256 afterBalance = address(c).balance;

        // attempt a withdraw of a very large amount to detect whether withdraw would succeed for this caller
        bool withdrawReverted;
        try c.withdraw(type(uint256).max) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // General invariant:
        // - If migrateTo was called and did not revert, it must not increase the contract's observable balance (afterBalance <= beforeBalance).
        // - If afterBalance == 0 then withdraw must revert (no funds left to withdraw for this caller).
        assert( ( !doMigrate || migrateReverted || afterBalance <= beforeBalance ) && ( afterBalance != 0 || withdrawReverted ) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: deposit an amount and check mapping and contract balance behavior
    function run(uint256 amount) public payable {
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= amount);

        // read before-values
        uint256 beforeMapping = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // perform the deposit call sending `amount` wei
        c.deposit{value: amount}();

        // read after-values
        uint256 afterMapping = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // General rule: deposit must not decrease the caller's recorded balance and must increase it by exactly amount
        // and the contract's Ether balance must increase by at least amount (transfer into contract may be slightly larger due to other concurrent effects, but here we assert non-decrease by amount)
        assert(afterMapping == beforeMapping + amount && afterContractBal >= beforeContractBal + amount);
    }

    // accept ETH so the test contract can be funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt to deposit an amount and check contract balance change and revert behavior
    function run(uint256 amount) public payable {
        // require this test contract has enough ETH to forward the desired amount
        require(address(this).balance >= amount);

        // read before-value: contract's Ether balance
        uint256 beforeContractBal = address(c).balance;

        // perform the deposit call sending `amount` wei and capture whether it reverted
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-value
        uint256 afterContractBal = address(c).balance;

        // General rule: if deposit did not revert then the contract's balance increased by exactly amount;
        // if it reverted then contract balance did not increase by amount (we allow it to be unchanged)
        assert((!reverted && afterContractBal == beforeContractBal + amount) || (reverted && afterContractBal == beforeContractBal));
    }

    // accept ETH so the test contract can be funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try withdrawing up to some amount; ensure observable invariants about balances and Ether flow.
    function run(uint256 amount) public payable {
        // No precondition on c's state; ensure this test contract can receive ETH from c if transfer happens
        // (the test harness supplies Ether to this contract as needed).

        // Read observable before-values
        uint256 beforeContractBal = address(c).balance;
        // balances mapping is not public in C (it's private), so we cannot read it directly. However withdraw requires
        // amount <= balances[msg.sender], so a successful withdraw will reduce address(c).balance by amount and
        // increase address(this).balance by amount. We can observe those.

        // Attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;
        uint256 afterThisBal = address(this).balance;

        // General rule:
        // - withdraw never increases the contract's balance: afterContractBal <= beforeContractBal
        // - if withdraw succeeded then contract balance decreased by exactly amount and this contract's balance increased by exactly amount
        // - if withdraw reverted then balances unchanged (contract balance unchanged and this contract's balance unchanged)
        assert((afterContractBal <= beforeContractBal) &&
               (( !reverted && afterContractBal + amount == beforeContractBal && afterThisBal >= amount) || (reverted && afterContractBal == beforeContractBal)));
    }

    // allow receiving ETH from c.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take no Ether input because refund() sends Ether out
    function run() public payable {
        // Preconditions: none about msg.value here. We will first deposit some Ether into c on behalf of this contract.
        // Ensure this contract has enough balance to deposit some amount. Use a parametrized deposit amount by reading address(this).balance
        uint256 initialSelfBal = address(this).balance;
        // choose a deposit amount at most initialSelfBal; pick half (non-deterministic in property-testing harness via choices of initial balance)
        uint256 depositAmount = initialSelfBal / 2;

        // If depositAmount is zero, still proceed: refund should then be a no-op and not increase contract balance.
        if (depositAmount > 0) {
            // call deposit on c sending Ether from this contract
            c.deposit{value: depositAmount}();
        }

        // Read observable values before refund
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeCallerRecorded = c.balances(address(this));

        // perform refund and capture whether it reverted
        bool reverted;
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable values after (if call didn't revert, state has changed; if reverted, state unchanged)
        uint256 afterContractBal = address(c).balance;
        uint256 afterCallerRecorded = c.balances(address(this));

        // General rule: If refund did not revert, caller's recorded balance is zero and contract's balance decreased by at least the previous recorded balance for caller.
        // If refund reverted, nothing is required (but we still assert a relation that holds in both cases):
        //   reverted OR (afterCallerRecorded == 0 && beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal >= beforeCallerRecorded)
        // Avoid underflow in assert by using comparisons only.
        assert(reverted || (afterCallerRecorded == 0 && beforeContractBal >= afterContractBal && (beforeContractBal - afterContractBal) >= beforeCallerRecorded));
    }

    // allow receiving Ether in case c.transfer triggers sending Ether to this contract during tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read the internal balances mapping (it's not public), so observe behavior via address(c).balance
    // and by performing a deposit then refund: net effect should send back at least what was deposited by this contract.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance to deposit");

        // Record contract balance before depositing
        uint256 beforeContractBal = address(c).balance;
        // Record our balance before deposit (as observable from this contract)
        uint256 beforeSelfBal = address(this).balance;

        // Make a deposit into c on behalf of this test contract
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Balance snapshots after deposit
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositSelfBal = address(this).balance;

        // Ensure deposit had the expected observable effect: contract balance increased by at most depositAmount and our balance decreased by at most depositAmount.
        // (This merely documents observations; will be used in the main assertion below.)

        // Attempt refund and capture whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // Balances after refund attempt
        uint256 finalContractBal = address(c).balance;
        uint256 finalSelfBal = address(this).balance;

        // General rule: Either the refund reverted, or if it succeeded then the caller (this contract) must have received at least the amount it had just deposited into c (as observed by net change in this contract's balance), and the contract's balance must have decreased by at least that deposited amount.
        // We express "at least the amount deposited" using the recorded afterDepositContractBal - finalContractBal >= depositAmount and finalSelfBal - afterDepositSelfBal >= depositAmount.
        // To be safe against any unexpected reentrancy transfers into the contract during these calls, we require the observed net outflow from c and net inflow to this contract to each be >= depositAmount when refund succeeded.
        assert(refundedReverted || ((afterDepositContractBal >= finalContractBal) && (afterDepositContractBal - finalContractBal >= depositAmount) && (finalSelfBal >= afterDepositSelfBal) && (finalSelfBal - afterDepositSelfBal >= depositAmount)));
    }

    receive() external payable {}
}

