        } catch {
            refundedReverted = true;
        }

        // Snapshots after refund attempt
        uint256 finalContractBal = address(c).balance;
        uint256 finalSelfBal = address(this).balance;

        // If refund succeeded, then the caller (this contract) must have received at least the amount it deposited above,
        // and the contract's balance must have decreased by at least that deposit amount. If refund reverted, no requirement.
        assert(refundedReverted || (
            // contract balance did not increase (final <= after-deposit) and decreased by at least depositAmount
            (afterDepositContractBal >= finalContractBal) && (afterDepositContractBal - finalContractBal >= depositAmount)
            &&
            // caller's balance did not decrease and increased by at least depositAmount
            (finalSelfBal >= afterDepositSelfBal) && (finalSelfBal - afterDepositSelfBal >= depositAmount)
        ));
    }

