contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function with all test logic
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // Snapshot observable balances before deposit
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeSelfBal = address(this).balance;

        // Perform deposit as a top-level state-changing call on c
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Snapshot after deposit
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositSelfBal = address(this).balance;

        // Attempt refund and capture whether it reverted (must be a top-level try)
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // Snapshot after refund attempt
        uint256 finalContractBal = address(c).balance;
        uint256 finalSelfBal = address(this).balance;

        // If refund succeeded, then the caller's observable ETH balance increased by at least depositAmount
        // and the contract's balance decreased by at least depositAmount.
        assert(refundedReverted || (
            // caller received at least what it deposited in this run
            (finalSelfBal >= afterDepositSelfBal) && (finalSelfBal - afterDepositSelfBal >= depositAmount)
            &&
            // contract lost at least that much
            (afterDepositContractBal >= finalContractBal) && (afterDepositContractBal - finalContractBal >= depositAmount)
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender; // the deployer of this test (not used further)
    }

    // single public function with all logic
    // param callerIsCreator: if true, we attempt to call migrateTo as the creator (which is the creator of c)
    // amount: Ether to send to c initially so migrateTo has some balance to transfer
    // to: destination address for migrateTo
    function run(bool callerIsCreator, uint256 amount, address payable to) public payable {
        require(address(this).balance >= amount, "insufficient balance for setup");

        // Fund the contract c by depositing Ether from this contract (which is msg.sender on calls into c)
        // deposit is a state-changing call and must be top-level
        if (amount > 0) {
            c.deposit{value: amount}();
        }

        // Snapshot contract balance before migrate attempt
        uint256 beforeBal = address(c).balance;

        bool migratedReverted;
        // We need to simulate two roles: creator and non-creator.
        // The checker deploys a fresh c where its creator was msg.sender at c's construction time.
        // In this testing harness, the InvMutTest contract deployed c, so the creator is the InvMutTest contract itself.
        // Therefore calling c.migrateTo from this contract will be as creator. To simulate non-creator, we call via a try from an external call context: we cannot change msg.sender inside this contract, so we only distinguish by the input flag and expect revert accordingly.

        // Call migrateTo as this contract (which is the creator of c). The call must be top-level.
        try c.migrateTo(to) {
            migratedReverted = false;
        } catch {
            migratedReverted = true;
        }

        // Snapshot after attempt
        uint256 afterBal = address(c).balance;

        // General rule:
        // If this contract is the creator (it is), then migrateTo should not leave contract with more than zero balance when it returns successfully: if it did not revert then afterBal == 0.
        // If it reverted, we allow afterBal to be unchanged or anything.
        // We encode the intended property using the callerIsCreator parameter to state the expectation: when callerIsCreator==true we assert that either the call reverted or afterBal==0.
        // When callerIsCreator==false we assert that the call must have reverted (since only creator can call migrateTo).

        if (callerIsCreator) {
            assert(migratedReverted || (afterBal == 0));
        } else {
            assert(migratedReverted);
        }
    }

    // accept Ether for deposits and migrations
    receive() external payable {}
}

