contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to deposit some amount then call refund and check invariants
    function run(uint256 depositAmount) public payable {
        // ensure this test contract can send the requested amount
        require(address(this).balance >= depositAmount);

        // observe the observable per-address balance before any actions
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // observe recorded balance after deposit attempt and before refund
        uint256 midRecorded = c.balances(address(this));
        uint256 midContractBalance = address(c).balance;
        uint256 midThisBalance = address(this).balance;

        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // observe after refund
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // General rule:
        // If refund did not revert then (1) the contract's recorded balance for this test
        // address is zero afterwards, and (2) the Ether the test contract gained from c
        // equals the reduction in the contract's observable balance (address(c).balance),
        // and (3) the amount transferred to the test contract equals the recorded balance
        // that existed immediately before calling refund (midRecorded).
        // We express (3) without subtraction underflow by comparing balances.
