        // If refund did not revert then (A) contract balance did not increase, i.e. contractBalanceAfter <= contractBalanceBefore,
        // and (B) a subsequent withdraw(1) must revert (recorded balance became zero so cannot withdraw 1 wei).
        assert(refundedReverted || (contractBalanceAfter <= contractBalanceBefore && withdraw1Reverted));
    }

    // allow receiving Ether back from C
    receive() external payable {}
}

contract InvMutTest {
