}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit and then try withdrawing up to that amount.
    // The test asserts the general rule: if deposit(value) is called with value>0 and succeeds,
    // then address(c).balance increases by value and a withdraw of value (or any u in [0,value]) will succeed.
    function run(uint256 value, uint256 withdrawAmount) public payable {
        require(true);
        // ensure this contract has enough balance to send 'value' to c
        if (value > 0) {
            require(address(this).balance >= value, "insufficient balance to fund deposit");
        }

        // record contract balance before deposit
        uint256 before = address(c).balance;

        // perform deposit; capture whether it reverted
        bool depositReverted = false;
        if (value > 0) {
            try c.deposit{value: value}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        } else {
            // calling deposit with 0 value is allowed by signature; perform it and observe
            try c.deposit{value: 0}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

        uint256 after = address(c).balance;

        // If deposit succeeded and value>0 then the contract balance must have increased by exactly value.
        // Also, if deposit succeeded then any withdrawAmount <= value should be withdrawable (i.e., withdraw call does not revert).
        bool withdrawReverted = false;
        // normalize withdrawAmount to be <= value when value>0; if value==0 we still allow withdrawAmount==0
        uint256 attemptWithdraw = withdrawAmount;
        if (value > 0) {
            // cap attemptWithdraw to value to express the property for any u in [0,value]
            if (attemptWithdraw > value) {
                attemptWithdraw = value;
            }
        } else {
            // when value==0, only allow withdrawAttempt==0 (withdraw >0 should revert per contract logic)
            if (attemptWithdraw != 0) {
                attemptWithdraw = 1; // will cause expected revert
            }
        }

        // attempt withdraw and record revert
        try c.withdraw(attemptWithdraw) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // General assertion combining the guarantees:
        // If deposit succeeded and value>0 then after - before == value AND withdraw of any u in [0,value]
        // (we tested one such u by capping withdrawAmount) must not revert.
        // If deposit reverted or value==0 then we make no claim that withdraw succeeded.
        assert(
            !(value > 0 && !depositReverted) || (after - before == value && withdrawReverted == false)
        );
    }

    // receive to accept refunds from C if needed
    receive() external payable {}
}

