contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: initialDeposit we will send to c, withdrawAmount to attempt
    function run(uint256 initialDeposit, uint256 withdrawAmount) public payable {
        require(true);
        // ensure this contract has enough balance to send 'initialDeposit' to c when needed
        if (initialDeposit > 0) {
            require(address(this).balance >= initialDeposit);
        }

        // Try to deposit initialDeposit (may revert if assert inside c fails)
        bool depositReverted;
        try c.deposit{value: initialDeposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Record c balance after deposit
        uint256 midBal = address(c).balance;

        // Attempt withdraw(withdrawAmount)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // After the withdraw attempt, we check whether a tiny subsequent withdraw of 1 would revert.
        // We don't actually perform that withdraw (would change state); instead, we infer the contract's
        // recorded balance relation via behaviour: if withdraw(withdrawAmount) succeeded then the
        // contract must have reduced its recorded balance for this caller by at least withdrawAmount,
        // which implies that if previously the caller had exactly withdrawAmount, a further withdraw(1)
        // would now revert. We express a general rule: if withdraw succeeded then either
        // (a) the contract's Ether balance decreased by at least withdrawAmount (observable), or
        // (b) if the contract's balance did not decrease that much then a subsequent withdraw(1)
        // must revert (we capture that by asserting withdraw succeeded implies address(c).balance
        // is <= midBal - withdrawAmount OR withdraw(1) would revert). Since we cannot call withdraw(1)
        // inside the assert, we use only observable balances and revert flag.

        // Read balance after withdraw attempt
        uint256 afterBal = address(c).balance;

        // The asserted invariant: if the attempted withdraw succeeded, then either the contract's
        // balance decreased by at least withdrawAmount, or the contract's balance decreased (possibly 0)
        // but we still require that afterBal <= midBal && (midBal - afterBal) >= withdrawAmount when possible.
        // To avoid underflow in the assert, compare with inequalities only.

        assert(
            withdrawReverted || (midBal >= afterBal && (midBal - afterBal >= withdrawAmount))
        );
    }

    receive() external payable {}
}
